{
  "name": "HDLC通信编解码器",
  "name_en": "HDLC Framing Codec",
  "manufacturer": "",
  "description": "用于对字节流进行 HDLC 成帧、转义、校验和解码的通信组件。它常用于实验系统中与采用 HDLC 风格链路层协议的仪器或嵌入式设备交换数据包；本体并非独立物理仪器，而是位于数据流接口上的协议处理模块。",
  "description_en": "A communication component for HDLC framing, byte escaping, checksum calculation, and packet decoding on a byte stream. It is commonly used in laboratory systems to exchange packets with instruments or embedded devices that use an HDLC-style link layer. It is not a standalone physical instrument, but a protocol-processing element on top of a stream interface.",
  "tag_hints": [
    "HDLC framing",
    "serial communication",
    "packet encoding",
    "packet decoding",
    "FCS16 checksum",
    "byte-stream transport"
  ],
  "actions": [
    {
      "action_name": "auto-mkfcstab",
      "description": "生成 FCS16 静态查找表",
      "description_en": "Generate the static lookup table for FCS16"
    },
    {
      "action_name": "auto-fcs16",
      "description": "根据输入字节更新 FCS16 校验值",
      "description_en": "Update the FCS16 checksum using the input byte"
    },
    {
      "action_name": "auto-collect",
      "description": "从数据流中同步并收集下一个有效 HDLC 数据包",
      "description_en": "Synchronize to the stream and collect the next valid HDLC packet"
    },
    {
      "action_name": "auto-encode_byte",
      "description": "对单个字节进行 HDLC 转义编码并追加到数据包",
      "description_en": "HDLC-encode a single byte and append it to a packet"
    },
    {
      "action_name": "auto-encode",
      "description": "将载荷编码为 HDLC 数据包",
      "description_en": "Encode a payload into an HDLC packet"
    },
    {
      "action_name": "auto-write",
      "description": "将数据编码为 HDLC 帧并写入数据流",
      "description_en": "Encode data as an HDLC frame and write it to the stream"
    },
    {
      "action_name": "auto-read",
      "description": "从数据流读取并解码下一个 HDLC 数据包",
      "description_en": "Read and decode the next HDLC packet from the stream"
    },
    {
      "action_name": "auto-valiter",
      "description": "迭代输出数据流中的解码值或数据包",
      "description_en": "Iterate over decoded values or packets from the stream"
    }
  ]
}

